mapper.select:
SELECT MSGID AS msgId, RECV_ID AS recvId, UTYPE AS uType, EMAIL AS eMail, NAME AS name, IP AS ip, COCD AS coCd, CONM AS coNm, SUBORGCD AS subOrgCd, SUBORGNM AS subOrgNm, BUSICD AS busiCd, BUSINM AS busiNm, DEPTCD AS deptCd, DEPTNM AS deptNm, JIKGUBCD AS jikgubCd, JIKGUBNM AS jikgubNm, INSIDE AS inSide FROM EMS_RECV WHERE MSGID = #{msgId}
AND UTYPE IN (${uType})
ORDER BY UTYPE, NAME

SELECT A.MSGID AS msgId, ATTACHID AS attachId, ATTACHNAME AS attachName, ATTACHPATH AS attachPath, ATTACHSIZE AS attachSize, ATTACHEXT AS attachExt, ATTACHDESC AS attachDesc, ATTACHHASH AS attachHash, ENCRYPTED AS encrypted, FILTERTYPE AS filterType, FLINK AS fLink, FLINKKEY AS fLinkKey, SUMMARY AS summary, SUBJECT AS subject, SVC AS svc, SRCIP AS srcIp, DSTIP AS dstIp, HOST AS host, PATH AS path, USERID AS userId, NAME AS name, DATE_FORMAT(CTIME,'%Y-%m-%d %H.%i.%S') AS ctime FROM EMS_ATTACH A, EMS_MESSAGE B WHERE A.MSGID = #{msgId} AND A.MSGID = B.MSGID
AND ATTACHID = #{attachId}
AND ATTACHPATH IS NOT NULL ORDER BY ATTACHNAME

SELECT  A.ATTACHNAME AS attachName, B.ATTACHTEXTPATH AS attachTextPath, B.ATTACHSIZE AS attachSize, B.ATTACHPATH AS attachPath, B.ATTACHEXT AS attachExt
FROM	EMS_ATTACH A, EMS_ATTACH_HASH B
WHERE	A.MSGID = #{msgId}
AND		A.ATTACHID = #{attachId}
AND		A.ATTACHHASH = B.ATTACHHASH
LIMIT	1

SELECT  ATTACHNAME AS attachName, KWDS AS kwds, AMOUNT AS total
FROM	EMS_PI
WHERE	MSGID = #{msgId}

AND		PI_ID = #{piId}


AND		TYPE = #{type}


AND		ATTACHNAME = #{attachName}

ORDER	BY ATTACHNAME, KWDS

SELECT  ADMIN_ID AS adminId, userid AS userid, MSGID AS msgId
FROM	UI_ADMIN_USERID_GENERATIVE
WHERE	ADMIN_ID = #{adminId}
AND		USERID = #{userid}
AND		TYPE = #{type}

AND		SRCIP = #{srcip}

SELECT  ADMIN_ID AS adminId, XROOTMTR AS xRootMtr, MSGID AS msgId
FROM	UI_ADMIN_XROOTMTR
WHERE	ADMIN_ID = #{adminId}
AND		XROOTMTR = #{xRootMtr}

	AND		SRCIP = #{srcip}

