SELECT 	STATUS_STR
FROM	UI_DOWNLOAD_BATCH
WHERE	DOWN_SEQ = #{downSeq}
AND		ADMIN_ID = #{adminId}

SELECT 	DOWN_SEQ AS downSeq, DOWN_VAL AS downVal, EXPORT_TYPE AS exportType, EXPORT_FILE_EXT AS exportFileExt, ADMIN_ID AS adminId, DATE_FORMAT(REQ_DT,'%Y-%m-%d %H:%i:%S') AS reqDt, DATE_FORMAT(END_DT,'%Y-%m-%d') AS endDt, DOWN_STATUS AS downStatus, STATUS_STR AS statusStr, DOWNFILE_PATH AS downFilePath, DOWNFILE_SIZE AS downFileSize, ING_ROWS AS ingRows, TOTAL_ROWS AS totalRows, SKIP_ROWS AS skipCnt, SKIP_TEXT AS skipText
FROM 	UI_DOWNLOAD_BATCH
WHERE 	ADMIN_ID = #{adminId}

AND 	EXPORT_TYPE = #{exportTypeSel}


AND 	EXPORT_FILE_EXT = #{fileExtSel}


AND 	STATUS_STR = #{statusSel}

ORDER 	BY REQ_DT DESC

LIMIT	${offset}, ${limit}

